package io.github.campione01.mineclientbridge;
import com.google.gson.*;
import java.nio.file.*;
import java.util.*;
/** Synthetic cold-shape DTOs via production Geometry/JSON. Never live world/target capture. */
public final class RecoverySurvivalV6ObservationWire {
 static JsonObject facts(boolean hit,boolean using){
  JsonObject j=new JsonObject();j.addProperty("complete",true);j.addProperty("food_level",12);j.addProperty("saturation",0);j.addProperty("is_using_item",using);j.addProperty("used_hand",using?"MAIN_HAND":null);j.addProperty("use_remaining_ticks",using?-1:0);j.addProperty("hurt_time",0);j.addProperty("entity_reach",3);j.addProperty("attack_strength",1);
  if(hit){JsonObject e=new JsonObject();e.addProperty("entity_id",17);e.addProperty("uuid",RecoverySurvivalV6Checks.TARGET);e.addProperty("type","minecraft:blaze");e.addProperty("provider_class","net.minecraft.world.entity.monster.Blaze");e.addProperty("alive",true);e.addProperty("health",20);var box=new JsonObject();box.addProperty("min_x",-167);box.addProperty("min_y",55);box.addProperty("min_z",8);box.addProperty("max_x",-166);box.addProperty("max_y",56.8);box.addProperty("max_z",9);e.add("bbox",box);e.add("point",RecoveryNavigationV4ObservationWire.xyz(-166.5,56,9));j.add("entity_hit",e);}else j.add("entity_hit",JsonNull.INSTANCE);return j;
 }
 static JsonObject add(JsonObject j,boolean hit,boolean using){j.addProperty("profile",RecoveryShortInputLedger.SURVIVAL_V6_PROFILE);j.addProperty("selected_slot",hit?8:1);j.add("survival",facts(hit,using));j.add("local_primed_tnt",new RecoveryMaintenanceV5.PrimedFacts(0,true,false).json());var hotbar=j.getAsJsonArray("hotbar");hotbar.set(1,RecoveryInteraction.describeHotbarStack(1,"minecraft:bread",4,0,0,"a".repeat(64),true));hotbar.set(8,RecoveryInteraction.describeHotbarStack(8,"minecraft:iron_axe",1,128,250,"a".repeat(64),true));if(using){j.addProperty("ready",false);j.addProperty("reason","one_in_flight");j.addProperty("active_id",new UUID(0,1).toString());}return j;}
 public static void main(String[] args)throws Exception{
  Path coldFile=Path.of(args[0]),out=Path.of(args[1]);Files.createDirectories(out);Map<String,JsonObject> cold=new HashMap<>();for(var row:JsonParser.parseString(Files.readString(coldFile)).getAsJsonObject().getAsJsonArray("blocks")){var j=row.getAsJsonObject();cold.put(j.get("x")+","+j.get("y")+","+j.get("z"),j);}
  var l=new RecoveryShortInputLedger(new RecoveryShortInputChecks.Memory(),()->100,false,true);RecoveryInteractionChecks.setLedger(l);var e=l.submit(RecoverySurvivalV6Checks.request(l,"look"));l.rejectQueued(e,"synthetic_bind");JsonArray cases=new JsonArray();
  for(boolean hit:new boolean[]{false,true})for(boolean using:new boolean[]{false,true}){var data=add(RecoveryNavigationV4ObservationWire.window(cold,-166.5,55,10.5),hit,using);RecoveryNavigationV4ObservationWire.save(out,"world-hit-"+hit+"-using-"+using+".json",data,cases,true);}
  var fail=add(RecoveryNavigationV4ObservationWire.window(cold,-166.5,55,10.5),false,false);fail.add("survival",RecoverySurvivalV6.unavailable());fail.addProperty("ready",false);fail.addProperty("reason","survival_observation_incomplete");RecoveryNavigationV4ObservationWire.save(out,"survival-failed.json",fail,cases,true);
  RecoveryNavigationV4ObservationWire.save(out,"no-world.json",NativeRecoveryShortInput.describeNoWorld(false,true,RecoveryShortInputLedger.SURVIVAL_V6_PROFILE),cases,true);
  for(boolean large:new boolean[]{false,true}){var maximum=add(RecoveryNavigationV4ObservationWire.window(cold,-166.5,55,10.5),true,false);var g=new RecoveryNavigationV4.Geometry(.6F);int index=0;for(var row:maximum.getAsJsonArray("local_blocks")){var c=row.getAsJsonObject();double[] b=large?new double[]{-.1234567890123456,-.2345678901234567,-.3456789012345678,.4567890123456789,.5678901234567891,.6789012345678912}:new double[]{0,0,0,1,1,1};g.shape(c,new RecoveryNavigationV4Checks.FakeShape(index++<32?16:0,b,false));}g.describe(maximum,true);RecoveryNavigationV4ObservationWire.save(out,large?"max512-long-overbudget.json":"max512-short.json",maximum,cases,!large);}
  var manifest=new JsonObject();manifest.addProperty("scope","Synthetic food/Blaze DTOs and cold model shapes via production geometry/codec, NOT native target/live capture");manifest.add("cases",cases);Files.write(out.resolve("manifest.json"),RecoveryShortInputCodec.encode(manifest));System.out.println(manifest);
 }
}
